import sys
from pathlib import Path

sys.path.insert(0, str(Path(".codex/skills/docx").resolve()))

from scripts.utilities import XMLEditor

# Elements that must follow w:u in CT_RPr ordering (ECMA-376)
AFTER_U = {
    "w:effect", "w:bdr", "w:shd", "w:fitText", "w:vertAlign", "w:rtl",
    "w:cs", "w:em", "w:lang", "w:eastAsianLayout", "w:specVanish", "w:oMath",
}

editor = XMLEditor("unpacked/word/document.xml")
dom = editor.dom
headlines = []

for p in dom.getElementsByTagName("w:p"):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild:
            parts.append(t.firstChild.data)
    text = "".join(parts)
    if not text.strip():
        continue
    # Headline: non-empty paragraph text with uppercase letters and no lowercase
    if any(c.isupper() for c in text) and not any(c.islower() for c in text):
        headlines.append(text.strip())
        for r in p.getElementsByTagName("w:r"):
            has_text = any(
                (t.firstChild and t.firstChild.data) for t in r.getElementsByTagName("w:t")
            ) or any(
                (dt.firstChild and dt.firstChild.data)
                for dt in r.getElementsByTagName("w:delText")
            )
            if not has_text:
                continue
            rPrs = r.getElementsByTagName("w:rPr")
            if rPrs:
                rPr = rPrs[0]
            else:
                rPr = dom.createElement("w:rPr")
                r.insertBefore(rPr, r.firstChild)
            if rPr.getElementsByTagName("w:u"):
                continue
            u = dom.createElement("w:u")
            u.setAttribute("w:val", "single")
            placed = False
            for child in rPr.childNodes:
                if child.nodeType == child.ELEMENT_NODE and child.tagName in AFTER_U:
                    rPr.insertBefore(u, child)
                    placed = True
                    break
            if not placed:
                rPr.appendChild(u)

editor.save()

print("Headlines underlined:", len(headlines))
for h in headlines:
    print(" -", h)

